def extract(chunk, max_gleanings):
    msgs = [EXTRACT_PROMPT.format(chunk)]
    out = llm(msgs); msgs.append(out)
    for i in range(max_gleanings):
        msgs.append(CONTINUE_PROMPT)
        more = llm(msgs); msgs.append(more)
        out += more
        if i >= max_gleanings - 1:
            break
        msgs.append(LOOP_PROMPT)
        if llm(msgs) != "Y":
            break
    return out

